# Tarjetas de la recopilación sobre el matrimonio de menores en las fuentes suníes (M01–M37).
# [[k:...]] naranja = frase clave; [[a:...]] azul = matiz, discrepancia o lo que juega en contra.
from mtafsir import TAF
SH = "shamela.ws (Maktaba Shamila; paginación igual a la edición impresa)"
S = "https://shamela.ws/book/"
HU = "hadithunlocked.com"
H = "https://hadithunlocked.com/"

def T(k, **kw):
    d = {x: y for x, y in TAF[k].items() if x not in ('d', 'who')}
    d['tag_who'] = TAF[k]['who']
    d.update(kw)
    return d

C = []
def add(sec, who, **kw):
    kw['sec'] = sec; kw.setdefault('tag_who', who); C.append(kw)

