add(2, "al-Tirmidhi (m. 279 H / 892)", specs=["mTir"],
 title="al-Tirmidhi: Ahmad e Ishaq y la huérfana de nueve años; y Aisha: «cuando la niña cumple nueve años, es mujer»",
 ref="al-Tirmidhi, al-Jamiʿ, comentario al hadiz 1109 (Kitab al-nikah, «lo que se dice sobre obligar a la huérfana a casarse»)", ar_ref="جامع الترمذي، عقب الحديث ١١٠٩", site=HU, url=H + "tirmidhi:1109",
 es=["Y algunos dijeron: no es válido casar a la huérfana hasta que llegue a la pubertad, ni hay opción [de anularlo] en el matrimonio; es lo que dicen Sufyan al-Thawri, al-Shafiʿi y otros sabios. [[k:Y dijeron Ahmad e Ishaq: si la huérfana cumple nueve años y la casan, y ella acepta, el matrimonio es válido]], y no tiene opción [de anularlo] cuando llegue a la pubertad; [[k:y lo argumentaron con el hadiz de Aisha]]: que el Profeta ﷺ consumó el matrimonio con ella cuando tenía nueve años. [[k:Y Aisha dijo: cuando la niña cumple nueve años, es mujer]]."],
 prueba="Al-Tirmidhi recoge que Ahmad ibn Hanbal e Ishaq ibn Rahawayh daban por válido casar a la huérfana de nueve años con su aceptación, apoyándose en Aisha, y cita a Aisha: a los nueve años la niña «es mujer».",
 ojo="La frase de Aisha la cita sin cadena. Al-Thawri y al-Shafiʿi exigen la pubertad para la huérfana; para la hija casada por su padre no la exigen (ver M08).")

